create extension if not exists "pgcrypto";
create type batch_status as enum ('planned', 'mashing', 'fermenting', 'distilling', 'aging', 'bottling', 'completed', 'archived');
create type alert_severity as enum ('info', 'warning', 'critical');
create table profiles (id uuid primary key references auth.users(id) on delete cascade, email text unique, full_name text, role text not null default 'operator', created_at timestamptz not null default now());
create table recipes (id uuid primary key default gen_random_uuid(), name text not null, category text, version integer not null default 1, batch_size_l numeric, estimated_og numeric, estimated_fg numeric, estimated_abv numeric, notes text, created_by uuid references profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table recipe_ingredients (id uuid primary key default gen_random_uuid(), recipe_id uuid not null references recipes(id) on delete cascade, ingredient_name text not null, ingredient_type text, amount numeric not null check (amount >= 0), unit text not null, cost numeric not null default 0 check (cost >= 0));
create table batches (id uuid primary key default gen_random_uuid(), recipe_id uuid references recipes(id), batch_number text not null unique, status batch_status not null default 'planned', target_yield_l numeric, actual_yield_l numeric, expected_abv numeric, final_abv numeric, start_date timestamptz, completed_date timestamptz, notes text, created_by uuid references profiles(id), created_at timestamptz not null default now());
create table fermentations (id uuid primary key default gen_random_uuid(), batch_id uuid not null references batches(id) on delete cascade, fermenter_name text, yeast_strain text, original_gravity numeric, current_gravity numeric, final_gravity numeric, ph numeric, temperature numeric, start_date timestamptz, end_date timestamptz);
create table fermentation_readings (id uuid primary key default gen_random_uuid(), fermentation_id uuid not null references fermentations(id) on delete cascade, gravity numeric, ph numeric, temperature numeric, reading_time timestamptz not null default now(), notes text);
create table distillation_runs (id uuid primary key default gen_random_uuid(), batch_id uuid not null references batches(id) on delete cascade, still_name text, run_type text, start_time timestamptz, end_time timestamptz, operating_proof numeric, total_collected_l numeric);
create table distillation_cuts (id uuid primary key default gen_random_uuid(), run_id uuid not null references distillation_runs(id) on delete cascade, cut_type text not null, volume_l numeric, proof numeric, recorded_at timestamptz not null default now());
create table barrels (id uuid primary key default gen_random_uuid(), barrel_code text not null unique, barrel_type text, char_level text, capacity_l numeric, warehouse_location text, fill_date timestamptz, status text not null default 'active');
create table barrel_readings (id uuid primary key default gen_random_uuid(), barrel_id uuid not null references barrels(id) on delete cascade, current_volume_l numeric, current_proof numeric, angel_share_percent numeric, tasting_notes text, reading_date timestamptz not null default now());
create table inventory_items (id uuid primary key default gen_random_uuid(), sku text unique, name text not null, category text, quantity numeric not null default 0, unit text, reorder_level numeric not null default 0, supplier text, cost numeric, created_at timestamptz not null default now());
create table inventory_transactions (id uuid primary key default gen_random_uuid(), inventory_item_id uuid not null references inventory_items(id), transaction_type text not null, quantity numeric not null, notes text, created_at timestamptz not null default now());
create table equipment (id uuid primary key default gen_random_uuid(), name text not null, equipment_type text, manufacturer text, serial_number text, status text, purchase_date date);
create table maintenance_logs (id uuid primary key default gen_random_uuid(), equipment_id uuid not null references equipment(id), maintenance_type text not null, notes text, completed_at timestamptz not null default now());
create table lab_tests (id uuid primary key default gen_random_uuid(), batch_id uuid references batches(id), test_type text not null, result numeric, unit text, technician text, created_at timestamptz not null default now());
create table ai_yield_predictions (id uuid primary key default gen_random_uuid(), batch_id uuid references batches(id), predicted_yield_l numeric, confidence_score numeric check (confidence_score between 0 and 100), predicted_abv numeric, predicted_hearts_l numeric, risk_score numeric check (risk_score between 0 and 100), created_at timestamptz not null default now());
create table ai_alerts (id uuid primary key default gen_random_uuid(), batch_id uuid references batches(id), severity alert_severity not null, title text not null, message text not null, estimated_loss_percent numeric, recommendation text, acknowledged boolean not null default false, created_at timestamptz not null default now());
create table sensor_readings (id bigint generated always as identity primary key, sensor_id text not null, batch_id uuid references batches(id), sensor_type text not null, reading_value numeric not null, unit text, recorded_at timestamptz not null default now());
create table dashboard_metrics (id uuid primary key default gen_random_uuid(), metric_name text not null, metric_value numeric, metric_unit text, updated_at timestamptz not null default now());
create table documents (id uuid primary key default gen_random_uuid(), batch_id uuid references batches(id), document_type text not null, file_url text not null, uploaded_at timestamptz not null default now());
create table qr_assets (id uuid primary key default gen_random_uuid(), entity_type text not null, entity_id uuid not null, qr_value text not null unique, created_at timestamptz not null default now());
create table audit_logs (id bigint generated always as identity primary key, user_id uuid references profiles(id), action text not null, table_name text not null, record_id text, created_at timestamptz not null default now());
do $$ declare table_name text; begin foreach table_name in array array['profiles','recipes','recipe_ingredients','batches','fermentations','fermentation_readings','distillation_runs','distillation_cuts','barrels','barrel_readings','inventory_items','inventory_transactions','equipment','maintenance_logs','lab_tests','ai_yield_predictions','ai_alerts','sensor_readings','dashboard_metrics','documents','qr_assets','audit_logs'] loop execute format('alter table %I enable row level security', table_name); execute format('create policy "Authenticated users can read %I" on %I for select to authenticated using (true)', table_name, table_name); end loop; end $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, email, full_name) values (new.id, new.email, new.raw_user_meta_data->>'full_name'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
